/*
======================================
; Title: sales-map.js
; Author: Red
; Date Created: 27 October 2026
; Last Updated: 27 October 2026
; Description: Hover and tap readout for the sales map on reviews.html (markup generated by scripts/sales_map.py). The map, the World / United States switch and the place table all work without it
; Sources Used: None
;=====================================
*/

(function() {
  // Smallest dot radius on screen, in px, so one-order towns stay visible on a phone.
  const MIN_DOT_PX = 3;
  // How far outside a dot (in screen px) the pointer still picks it.
  const DOT_REACH_PX = 10;

  function setUp(figure) {
    const svg = figure.querySelector(".sales-map-svg");
    if (!svg) {
      return;
    }

    // The <title> on each mark is the no-JavaScript fallback; drop it so the browser's tooltip doesn't double up.
    svg.querySelectorAll("[data-label] > title").forEach(function(title) {
      title.remove();
    });

    const dots = Array.from(svg.querySelectorAll(".sm-dot[data-orders]"));
    const tip = document.createElement("div");
    const tipValue = document.createElement("strong");
    const tipLabel = document.createElement("span");
    tip.className = "sales-map-tip";
    tip.hidden = true;
    tip.setAttribute("aria-hidden", "true");
    tip.append(tipValue, tipLabel);
    figure.appendChild(tip);
    let active = null;

    function screenScale() {
      const width = svg.viewBox.baseVal.width;
      return width ? svg.getBoundingClientRect().width / width : 0;
    }

    function sizeDots() {
      const scale = screenScale();
      if (!scale) {
        return;
      }
      dots.forEach(function(dot) {
        dot.setAttribute("r", Math.max(parseFloat(dot.dataset.r), MIN_DOT_PX / scale));
      });
    }

    function nearestDot(event) {
      const ctm = svg.getScreenCTM();
      const scale = screenScale();
      if (!ctm || !scale) {
        return null;
      }
      const point = new DOMPoint(event.clientX, event.clientY).matrixTransform(ctm.inverse());
      let best = null;
      let bestDistance = Infinity;
      dots.forEach(function(dot) {
        const distance = Math.hypot(dot.cx.baseVal.value - point.x, dot.cy.baseVal.value - point.y);
        if (distance <= dot.r.baseVal.value + DOT_REACH_PX / scale && distance < bestDistance) {
          best = dot;
          bestDistance = distance;
        }
      });
      return best;
    }

    function place(event) {
      const box = figure.getBoundingClientRect();
      const x = event.clientX - box.left;
      const y = event.clientY - box.top;
      let left = x + 14;
      if (left + tip.offsetWidth > box.width) {
        left = Math.max(0, x - 14 - tip.offsetWidth);
      }
      let top = y - tip.offsetHeight - 12;
      if (top < 0) {
        top = y + 18;
      }
      tip.style.left = left + "px";
      tip.style.top = top + "px";
    }

    function show(mark, event) {
      if (active !== mark) {
        hide();
        active = mark;
        mark.classList.add("is-active");
      }
      const orders = parseInt(mark.dataset.orders, 10);
      if (isNaN(orders)) {
        tipValue.textContent = mark.dataset.label;
        tipLabel.textContent = "";
      } else {
        tipValue.textContent = orders.toLocaleString() + (orders === 1 ? " order" : " orders");
        tipLabel.textContent = mark.dataset.label;
      }
      tip.hidden = false;
      place(event);
    }

    function hide() {
      if (active) {
        active.classList.remove("is-active");
      }
      active = null;
      tip.hidden = true;
    }

    function track(event) {
      const mark = nearestDot(event) || event.target.closest("[data-label]");
      if (mark && svg.contains(mark)) {
        show(mark, event);
      } else {
        hide();
      }
    }

    svg.addEventListener("pointermove", track);
    svg.addEventListener("pointerdown", track);
    svg.addEventListener("pointerleave", function(event) {
      if (event.pointerType === "mouse") {
        hide();
      }
    });
    document.addEventListener("pointerdown", function(event) {
      if (!svg.contains(event.target)) {
        hide();
      }
    });
    window.addEventListener("resize", sizeDots);
    document.querySelectorAll(".sales-map-radio").forEach(function(radio) {
      radio.addEventListener("change", function() {
        hide();
        sizeDots();
      });
    });
    sizeDots();
  }

  function init() {
    document.querySelectorAll(".sales-map-figure").forEach(setUp);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
